-- Venue Live Guest "Buka Puasa Bersama". Aditif & idempoten. Jalankan SETELAH admin-live-event-aqiqah.sql (jenis acara bukapuasa), admin-live-theme.sql, admin-live-decor.sql, admin-live-decor-avatars.sql, dan admin-live-decor-garden-layout.sql (skrip tata letak itu melewati venue ini karena ukuran/posisi dekornya diatur sendiri).
insert into public.live_venues (key, name, event_type, areas, max_guests, active, sort, bg_pos, nm_theme)
select 'bukapuasa', 'Buka Puasa Bersama (Ramadan)', 'bukapuasa', coalesce((select areas from public.live_venues where key = 'little-ballerina'), '[]'::jsonb), 300, false, 124, 'center 38%',
  $t${"name":"Buka Puasa","orn":"diamond","ui":{"ivory":"#FFF8E6","white":"#FFFFFF","soft":"#F3E6BF","soft2":"#C9B77A","accent":"#0F6B57","deep":"#073B30","ink":"#1B2E27","mute":"#5F7A6F","line":"#E3D6A8","serif":"\"Cormorant Garamond\",serif","sans":"Inter,system-ui,sans-serif","rad":18,"btnr":14,"btnt":"none","btnls":".02em"},"mono":{"font":"\"Cormorant Garamond\",serif","it":0,"paper":"#FFFBEF","ink":"#1B2E27","accent":"#0F6B57","gold":"#C9A227","leaf":"#E6F1E8","hbg":"rgba(255,248,230,.94)","hline":"#C9B77A","motif":"diamond"},"hud":{"bg":"rgba(7,59,48,.86)","acc":"#F2D98A","on":"#1B2E27"},"scr":{"wine":"#073B30","veil":"255,248,230"}}$t$::jsonb
where not exists (select 1 from public.live_venues where key = 'bukapuasa');
update public.live_venues set decor = $d${"speakers":{"url":"/assets/live-decor/bukapuasa/speakers.webp","w":2.2},"balloons":{"url":"/assets/live-decor/bukapuasa/balloons.webp","w":1.6},"stall_snacks":{"url":"/assets/live-decor/bukapuasa/stall_snacks.webp","w":2.0},"stall_candy":{"url":"/assets/live-decor/bukapuasa/stall_candy.webp","w":1.4},"stall_drinks":{"url":"/assets/live-decor/bukapuasa/stall_drinks.webp","w":4.8},"photobooth":{"url":"/assets/live-decor/bukapuasa/photobooth.webp","w":5.6},"claw":{"url":"/assets/live-decor/bukapuasa/claw.webp","w":4.4},"arch":{"url":"/assets/live-decor/bukapuasa/arch.webp"},"fountain":{"url":"/assets/live-decor/bukapuasa/fountain.webp","w":5.8},"sign":{"url":"/assets/live-decor/bukapuasa/sign.webp","w":1.5},"easel":{"url":"/assets/live-decor/bukapuasa/easel.webp","w":2.8,"x":4.6,"z":8.2},"table":{"url":"/assets/live-decor/bukapuasa/table.webp"},"banner":{"url":"/assets/live-decor/bukapuasa/banner.webp","w":1.3},"gifts":{"url":"/assets/live-decor/bukapuasa/gifts.webp","w":1.8},"av_host":{"url":"/assets/live-decor/bukapuasa/av_host.webp","name":"Pak Haji Peci Putih"},"av_l1":{"url":"/assets/live-decor/bukapuasa/av_l1.webp","name":"Pak Haji Peci Putih"},"av_l2":{"url":"/assets/live-decor/bukapuasa/av_l2.webp","name":"Kak Kacamata"},"av_l3":{"url":"/assets/live-decor/bukapuasa/av_l3.webp","name":"Kak Peci Hijau"},"av_l4":{"url":"/assets/live-decor/bukapuasa/av_l4.webp","name":"Kak Songkok Hijau"},"av_p1":{"url":"/assets/live-decor/bukapuasa/av_p1.webp","name":"Kak Hijab Hijau"},"av_p2":{"url":"/assets/live-decor/bukapuasa/av_p2.webp","name":"Kak Sanggul Bunga"},"av_p3":{"url":"/assets/live-decor/bukapuasa/av_p3.webp","name":"Kak Hijab Krem"}}$d$::jsonb, background_url = '/assets/live-decor/bukapuasa/painting.webp', active = true, updated_at = now() where key = 'bukapuasa';
